363	
364	void BpeTokenizer::EnsureSpecialTokens(const SpecialTokensConfig& spec, bool add_if_missing) {
365	    auto ensure = [&](const std::optional<std::string>& name, int& id_slot) {
366	        if (!name.has_value()) { id_slot = -1; return; }
367	        auto it = token_to_id_.find(*name);
368	        if (it != token_to_id_.end()) {
369	            id_slot = it->second;
370	            return;
371	        }
372	        if (!add_if_missing) {
373	            id_slot = -1;
374	            return;
375	        }
376	        id_slot = static_cast<int>(id_to_token_.size());
377	        id_to_token_.push_back(*name);
378	        token_to_id_.emplace(*name, id_slot);
379	    };
380	
381	    ensure(spec.bos_token, special_ids_.bos_id);
382	    ensure(spec.eos_token, special_ids_.eos_id);
383	    ensure(spec.unk_token, special_ids_.unk_id);
384	    ensure(spec.sep_token, special_ids_.sep_id);
385	    ensure(spec.pad_token, special_ids_.pad_id);
386	    ensure(spec.cls_token, special_ids_.cls_id);
387	    ensure(spec.mask_token, special_ids_.mask_id);
388	}
389	
390	void BpeTokenizer::AddAdditionalSpecialToken(const std::string& token,
391	                                             bool add_if_missing) {
392	    if (token.empty()) return;
393	
394	    // 已经是 additional_special_token 的话直接返回
395	    auto it_exist = additional_special_token_to_id_.find(token);
396	    if (it_exist != additional_special_token_to_id_.end()) {
397	        return;
398	    }
399	
400	    int id = -1;
401	    auto it = token_to_id_.find(token);
402	    if (it != token_to_id_.end()) {
403	        id = it->second;
404	    } else if (add_if_missing) {
405	        id = static_cast<int>(id_to_token_.size());
406	        id_to_token_.push_back(token);
407	        token_to_id_.emplace(token, id);
408	    } else {
409	        // 既不在 vocab 中，也不允许新增，直接忽略
410	        return;
411	    }
412	
413	    additional_special_tokens_.push_back(token);
414	    additional_special_token_ids_.push_back(id);
415	    additional_special_token_to_id_.emplace(token, id);
416	    additional_special_id_set_.insert(id);
417	}
418	
419	void BpeTokenizer::SetAdditionalSpecialTokens(const std::vector<std::string>& tokens,
420	                                              bool add_if_missing) {
421	    additional_special_tokens_.clear();
422	    additional_special_token_ids_.clear();
423	    additional_special_token_to_id_.clear();
424	    additional_special_id_set_.clear();
425	
426	    for (const auto& t : tokens) {
427	        AddAdditionalSpecialToken(t, add_if_missing);
428	    }
429	}

